create or replace function settle_financial_entry(entry_id uuid) returns financial_entries language plpgsql security invoker set search_path = public as $$ declare result financial_entries; begin update financial_entries set status = 'paid', paid_date = current_date, paid_at = now(), paid_by = auth.uid() where id = entry_id and is_company_member(company_id) and status not in ('paid','cancelled') returning * into result; if result.id is null then raise exception 'Lançamento não encontrado, cancelado ou já baixado'; end if; insert into audit_logs(company_id,user_id,action,entity,entity_id,new_data) values(result.company_id,auth.uid(),'finance.settled','FinancialEntry',result.id,to_jsonb(result)); return result; end; $$;

create or replace function cancel_sale(target_sale uuid) returns sales language plpgsql security invoker as $$ declare result sales; item jsonb; product_row products; begin select * into result from sales where id = target_sale and is_company_member(company_id) for update; if result.id is null then raise exception 'Venda não encontrada'; end if; if result.status = 'cancelled' then return result; end if; for item in select * from jsonb_array_elements(result.items) loop select * into product_row from products where id = (item->>'product_id')::uuid for update; update products set stock = stock + (item->>'qty')::numeric where id = product_row.id; insert into stock_movements(company_id, product_id, sale_id, type, quantity, reason) values(result.company_id, product_row.id, result.id, 'in', (item->>'qty')::numeric, 'Estorno de venda'); end loop; update financial_entries set status = 'cancelled' where sale_id = result.id and status <> 'cancelled'; update sales set status = 'cancelled' where id = result.id returning * into result; return result; end; $$;
